const rows = $input.all().map(i => i.json);

if (rows.length === 0 || !rows[0].user_id) {
  return [{ json: { identidade_encontrada: false } }];
}

const owners = rows
  .filter(r => r.owner_id)
  .map(r => ({ id: r.owner_id, name: r.owner_name, is_joint: r.is_joint }));

const owner_id_direto = rows[0].owner_id_direto || null;
const identificado_por_telefone_proprio = !!owner_id_direto;
const multi_ativo = rows[0].multi_owner_status === 'ativo';

// So pergunta entre os 3 (Titular1/Titular2/Ambos) quando NAO foi possivel identificar
// diretamente pelo telefone do titular.
const precisa_selecionar_proprietario = owners.length > 1 && multi_ativo && !identificado_por_telefone_proprio;

// Separa por papel (nao por posicao de criacao): titulares individuais x perfil conjunto ("Ambos").
const individuais = owners.filter(o => !o.is_joint);
const conjunta = owners.find(o => o.is_joint) || null;
const titular1 = individuais[0] || null;
const titular2 = individuais[1] || null;

// Quando ja identificado por telefone proprio, so falta perguntar "voce ou Ambos" (2 vias),
// e so faz sentido perguntar isso se o multi-titular estiver ativo e existir um perfil conjunto.
const titularIdentificado = identificado_por_telefone_proprio
  ? (individuais.find(o => o.id === owner_id_direto) || null)
  : null;
const precisa_perguntar_ambos = identificado_por_telefone_proprio && multi_ativo && !!conjunta;

// Os 3 slots (Titular1/Titular2/Conjunta) so aparecem preenchidos nos casos em que a IA
// realmente precisa perguntar algo (3 vias OU 2 vias) -- no caso comum, tudo fica "Nao existe".
const owner_id_titular1 = precisa_selecionar_proprietario && titular1 ? titular1.id : 'Não existe';
const owner_nome_titular1 = precisa_selecionar_proprietario && titular1 ? titular1.name : 'Não existe';
const owner_id_titular2 = precisa_selecionar_proprietario && titular2 ? titular2.id : 'Não existe';
const owner_nome_titular2 = precisa_selecionar_proprietario && titular2 ? titular2.name : 'Não existe';
const owner_id_conjunta = (precisa_selecionar_proprietario || precisa_perguntar_ambos) && conjunta ? conjunta.id : 'Não existe';
const owner_nome_conjunta = (precisa_selecionar_proprietario || precisa_perguntar_ambos) && conjunta ? conjunta.name : 'Não existe';

return [{
  json: {
    identidade_encontrada: true,
    user_id: rows[0].user_id,
    user_full_name: rows[0].user_full_name,
    owners,
    owner_count: owners.length,
    owner_id: identificado_por_telefone_proprio
      ? owner_id_direto
      : (precisa_selecionar_proprietario ? null : (owners[0] ? owners[0].id : null)),
    owner_name: identificado_por_telefone_proprio
      ? (titularIdentificado ? titularIdentificado.name : null)
      : (precisa_selecionar_proprietario ? null : (owners[0] ? owners[0].name : null)),
    identificado_por_telefone_proprio,
    precisa_selecionar_proprietario,
    precisa_perguntar_ambos,
    owner_id_titular1,
    owner_nome_titular1,
    owner_id_titular2,
    owner_nome_titular2,
    owner_id_conjunta,
    owner_nome_conjunta
  }
}];

